// CoordenadasBaseURL is the OVCCoordenadas SOAP/ASMX endpoint. It returns XML
// (the .svc/json/ path returns 404 for Coordenadas, unlike Callejero).
const CoordenadasBaseURL = "https://ovc.catastro.meh.es/ovcservweb/OVCSWLocalizacionRC"

// coordResponse is the XML envelope returned by Consulta_RCCOOR / _CPMRC /
// _Distancia. Catastro uses several root names (`consulta_coordenadas`,
// `consulta_coordenadas_distancias`) — we don't bind to one specific root so
// the parser accepts all of them.
type coordResponse struct {
	Control    coordControl    `xml:"control"`
	Coordinate []coordEntry    `xml:"coordenadas>coord"`
	Errors     []coordErr      `xml:"lerr>err"`
	Refcat     []coordRefEntry `xml:"coordenadas_distancias>coordd>lpcd>pcd"`
	RefcatAlt  []coordRefEntry `xml:"coordenadas_distancia>coordd>lpcd>pcd"`
}

type coordControl struct {
	CUCoor int `xml:"cucoor"`
	CUErr  int `xml:"cuerr"`
}

type coordEntry struct {
	PC   string `xml:"pc>pc1"`
	PC2  string `xml:"pc>pc2"`
	GEO  string `xml:"geo>xcen"`
	GEOY string `xml:"geo>ycen"`
	SRS  string `xml:"geo>srs"`
	Ldt  string `xml:"ldt"`
}

type coordRefEntry struct {
	PC1 string `xml:"pc>pc1"`
	PC2 string `xml:"pc>pc2"`
	Dis string `xml:"dis"`
	Ldt string `xml:"ldt"`
}

type coordErr struct {
	Cod string `xml:"cod"`
	Des string `xml:"des"`
}

// coordenadasGET calls a Coordenadas ASMX operation via HTTP GET (the SOAP
// service exposes simple GET bindings) and parses the XML response into JSON.
func coordenadasGET(timeout time.Duration, op string, params map[string]string) (json.RawMessage, error) {
	u := CoordenadasBaseURL + "/OVCCoordenadas.asmx/" + op
	q := url.Values{}
	for k, v := range params {
		q.Set(k, v)
	}
	full := u + "?" + q.Encode()

	httpClient := &http.Client{Timeout: timeout}
	req, err := http.NewRequest("GET", full, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "catastro-pp-cli")
	req.Header.Set("Accept", "application/xml,text/xml")
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("coordenadas GET %s: %w", op, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode >= 400 {
		return nil, fmt.Errorf("coordenadas %s: HTTP %d", op, resp.StatusCode)
	}

	var parsed coordResponse
	if err := xml.Unmarshal(body, &parsed); err != nil {
		return nil, fmt.Errorf("parse XML %s: %w", op, err)
	}
	if parsed.Control.CUErr > 0 && len(parsed.Errors) > 0 {
		return nil, fmt.Errorf("catastro error %s: %s", parsed.Errors[0].Cod, parsed.Errors[0].Des)
	}

	// Marshal to a flat JSON shape that's pleasant for users.
	type outCoord struct {
		RC      string `json:"rc"`
		Lon     string `json:"lon"`
		Lat     string `json:"lat"`
		SRS     string `json:"srs"`
		Address string `json:"address,omitempty"`
	}
	type outRef struct {
		RC       string  `json:"rc"`
		Distance float64 `json:"distance_m"`
	}
	type outShape struct {
		Coordinates []outCoord `json:"coordinates,omitempty"`
		References  []outRef   `json:"references,omitempty"`
	}

	var out outShape
	for _, c := range parsed.Coordinate {
		out.Coordinates = append(out.Coordinates, outCoord{
			RC:      c.PC + c.PC2,
			Lon:     c.GEO,
			Lat:     c.GEOY,
			SRS:     c.SRS,
			Address: c.Ldt,
		})
	}
	allRefs := append([]coordRefEntry{}, parsed.Refcat...)
	allRefs = append(allRefs, parsed.RefcatAlt...)
	for _, r := range allRefs {
		dis := 0.0
		fmt.Sscanf(r.Dis, "%f", &dis)
		out.References = append(out.References, outRef{
			RC:       r.PC1 + r.PC2,
			Distance: dis,
		})
	}

	return json.Marshal(out)
}

func newGeocodeCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "geocode",
		Short: "Geocodificación entre coordenadas y referencias catastrales (OVCCoordenadas)",
		Long: "Convierte coordenadas a referencias catastrales y viceversa usando los servicios " +
			"OVCCoordenadas del Catastro (Consulta_RCCOOR, Consulta_CPMRC, Consulta_RCCOOR_Distancia). " +
			"Estos endpoints devuelven XML que el cliente parsea internamente.",
	}
	cmd.AddCommand(newGeocodeReverseCmd(flags))
	cmd.AddCommand(newGeocodeForwardCmd(flags))
	cmd.AddCommand(newGeocodeNearbyCmd(flags))
	cmd.AddCommand(newGeocodeMunicipalityCmd(flags))
	return cmd
}

func newGeocodeReverseCmd(flags *rootFlags) *cobra.Command {
	var lon, lat, srs string
	cmd := &cobra.Command{
		Use:   "reverse",
		Short: "Coordenadas → referencia catastral (Consulta_RCCOOR)",
		Long: "Dada una coordenada (X, Y) en un SRS, devuelve la referencia catastral exacta que contiene\n" +
			"ese punto. Usa Consulta_RCCOOR de OVCCoordenadas.",
		Example: "  catastro-pp-cli geocode reverse --lon -3.70379 --lat 40.41678 --srs EPSG:4326 --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if lon == "" || lat == "" {
				return cmd.Help()
			}
			if srs == "" {
				srs = "EPSG:4326"
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_call":"Consulta_RCCOOR","lon":%q,"lat":%q,"srs":%q}`+"\n", lon, lat, srs)
				return nil
			}
			data, err := coordenadasGET(flags.timeout, "Consulta_RCCOOR", map[string]string{
				"SRS":          srs,
				"Coordenada_X": lon,
				"Coordenada_Y": lat,
			})
			if err != nil {
				return err
			}
			return printJSONFiltered(cmd.OutOrStdout(), json.RawMessage(data), flags)
		},
	}
	cmd.Flags().StringVar(&lon, "lon", "", "Coordenada X (longitud en EPSG:4326)")
	cmd.Flags().StringVar(&lat, "lat", "", "Coordenada Y (latitud en EPSG:4326)")
	cmd.Flags().StringVar(&srs, "srs", "EPSG:4326", "Sistema de referencia espacial (EPSG:4326, EPSG:25830, etc.)")
	_ = cliutil.IsVerifyEnv // silence unused if helper not used
	return cmd
}

func newGeocodeForwardCmd(flags *rootFlags) *cobra.Command {
	var rc, srs, prov, muni string
	cmd := &cobra.Command{
		Use:     "forward <RC>",
		Short:   "Referencia catastral → coordenadas (Consulta_CPMRC)",
		Example: "  catastro-pp-cli geocode forward 0545206VK4704F0001RE --srs EPSG:25830 --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				rc = args[0]
			}
			if rc == "" {
				return cmd.Help()
			}
			if srs == "" {
				srs = "EPSG:4326"
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_call":"Consulta_CPMRC","rc":%q,"srs":%q}`+"\n", rc, srs)
				return nil
			}
			// Consulta_CPMRC expects the 14-character parcel reference. RCs
			// longer than 14 chars (18/20) include subparcela suffix that the
			// service rejects with error 18.
			rc14 := rc
			if len(rc14) > 14 {
				rc14 = rc14[:14]
			}
			data, err := coordenadasGET(flags.timeout, "Consulta_CPMRC", map[string]string{
				"Provincia": prov,
				"Municipio": muni,
				"SRS":       srs,
				"RC":        rc14,
			})
			if err != nil {
				return err
			}
			return printJSONFiltered(cmd.OutOrStdout(), json.RawMessage(data), flags)
		},
	}
	cmd.Flags().StringVar(&srs, "srs", "EPSG:4326", "Sistema de referencia espacial de salida")
	cmd.Flags().StringVar(&prov, "provincia", "", "Provincia (opcional si la RC tiene 20 dígitos)")
	cmd.Flags().StringVar(&muni, "municipio", "", "Municipio (opcional si la RC tiene 20 dígitos)")
	return cmd
}

