func newGeocodeMunicipalityCmd(flags *rootFlags) *cobra.Command {
	var lon, lat string
	cmd := &cobra.Command{
		Use:   "municipality",
		Short: "Coordenadas → código INE del municipio",
		Long: "Atajo que llama a `nearby` y devuelve solo el código INE del municipio donde caen las\n" +
			"coordenadas. Útil para encadenar con `streets`, `municipalities`, etc.",
		Example: "  catastro-pp-cli geocode municipality --lon -3.70379 --lat 40.41678",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if lon == "" || lat == "" {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_call":"Consulta_RCCOOR_Distancia (then extract muni from RC)","lon":%q,"lat":%q}`+"\n", lon, lat)
				return nil
			}
			data, err := coordenadasGET(flags.timeout, "Consulta_RCCOOR_Distancia", map[string]string{
				"SRS":          "EPSG:4326",
				"Coordenada_X": lon,
				"Coordenada_Y": lat,
			})
			if err != nil {
				return err
			}
			var resp struct {
				References []struct {
					RC string `json:"rc"`
				} `json:"references"`
			}
			if err := json.Unmarshal(data, &resp); err != nil {
				return err
			}
			if len(resp.References) == 0 {
				return fmt.Errorf("no parcels found near (%s, %s)", lon, lat)
			}
			// RC characters 1-2 = INE province, 3-5 = INE municipality
			rc := resp.References[0].RC
			if len(rc) < 5 {
				return fmt.Errorf("invalid RC returned: %q", rc)
			}
			out := map[string]string{
				"province_code":     rc[0:2],
				"municipality_code": rc[2:5],
				"sample_rc":         rc,
			}
			b, _ := json.MarshalIndent(out, "", "  ")
			fmt.Fprintln(cmd.OutOrStdout(), strings.TrimSpace(string(b)))
			return nil
		},
	}
	cmd.Flags().StringVar(&lon, "lon", "", "Coordenada X (EPSG:4326)")
	cmd.Flags().StringVar(&lat, "lat", "", "Coordenada Y (EPSG:4326)")
	return cmd
}
